      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : CommSemiring R] (e : σ →₀ ℕ) (r : R),\n  (MvPowerSeries.monomial e) r = MvPowerSeries.C r * e.prod fun s e => MvPowerSeries.X s ^ e"
    },
    {
      "name": "MvPowerSeries.substAlgHom_monomial",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S]\n  [inst_2 : Algebra R S] {a : σ → MvPowerSeries τ S} (ha : MvPowerSeries.HasSubst a) (e : σ →₀ ℕ) (r : R),\n  (MvPowerSeries.substAlgHom ha) ((MvPowerSeries.monomial e) r) =\n    (algebraMap R (MvPowerSeries τ S)) r * e.prod fun s n => a s ^ n"
    },
    {
      "name": "MvPolynomial.monic_monomial_eq",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (m : σ →₀ ℕ),\n  (MvPolynomial.monomial m) 1 = m.prod fun n e => MvPolynomial.X n ^ e"
    },
    {
      "name": "MvPowerSeries.subst_monomial",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S]\n  [inst_2 : Algebra R S] {a : σ → MvPowerSeries τ S},\n  MvPowerSeries.HasSubst a →\n    ∀ (e : σ →₀ ℕ) (r : R),\n      MvPowerSeries.subst a ((MvPowerSeries.monomial e) r) =\n        (algebraMap R (MvPowerSeries τ S)) r * e.prod fun s n => a s ^ n"
    },
    {
      "name": "MvPowerSeries.coeff_subst",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S]\n  [inst_2 : Algebra R S] {a : σ → MvPowerSeries τ S},\n  MvPowerSeries.HasSubst a →\n    ∀ (f : MvPowerSeries σ R) (e : τ →₀ ℕ),\n      (MvPowerSeries.coeff e) (MvPowerSeries.subst a f) =\n        ∑ᶠ (d : σ →₀ ℕ), (MvPowerSeries.coeff d) f • (MvPowerSeries.coeff e) (d.prod fun s e => a s ^ e)"
    },
    {
      "name": "MvPowerSeries.monomial_one_eq",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : CommSemiring R] (e : σ →₀ ℕ),\n  (MvPowerSeries.monomial e) 1 = e.prod fun s n => MvPowerSeries.X s ^ n"
    }
  ]
}

